WITH enriched AS (SELECT *, RANK() OVER w_grp AS salary_rank, LAG(salary, 1) OVER w_hist AS prev_salary, AVG(salary) OVER (PARTITION BY level, job_title ORDER BY hire_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS salary_avg_3 FROM employees WINDOW w_grp AS (PARTITION BY job_title ORDER BY salary DESC), w_hist AS (PARTITION BY job_title, manager_id ORDER BY salary, id)) SELECT dept_id, job_title, MAX(salary_avg_3) AS max_salary_avg_3, COUNT_IF(level = 'L4') AS l4_events, PERCENTILE_APPROX(salary_rank, ARRAY(0.25, 0.5, 0.75)) AS salary_rank_quartiles, COUNT(*) FILTER (WHERE level = 'L5') AS l5_rows, SIZE(COLLECT_SET(job_title)) AS num_job_titles, SORT_ARRAY(COLLECT_SET(job_title)) AS job_title_list FROM enriched GROUP BY dept_id, job_title;
